<?php if(!defined('ABSPATH'))exit; ?><!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php the_archive_title(); ?> · <?php bloginfo('name'); ?></title><?php wp_head(); ?></head><body <?php body_class(); ?>><?php wp_body_open(); ?><header class="header"><div class="container"><a class="brand" href="<?php echo esc_url(home_url('/')); ?>"><?php bloginfo('name'); ?></a><nav class="nav"><a href="<?php echo esc_url(home_url('/')); ?>">Home</a></nav></div></header><main class="stories"><div class="container"><div class="section-title"><h1><?php the_archive_title(); ?></h1><span><?php echo esc_html($wp_query->found_posts); ?> posts</span></div><?php if(have_posts()):while(have_posts()):the_post(); ?><article class="story"><div class="tag"><?php $cats=get_the_category();if($cats)echo esc_html($cats[0]->name); ?></div><div><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),28)); ?></p><div class="post-tags"><?php the_tags('', ' · ', ''); ?></div></div><div class="date"><?php echo esc_html(get_the_date('F j, Y')); ?></div></article><?php endwhile;the_posts_pagination();else: ?><div class="empty">Nothing published in this archive yet.</div><?php endif; ?></div></main><footer class="footer"><div class="container">© <?php echo date('Y'); ?> <?php bloginfo('name'); ?></div></footer><?php wp_footer(); ?></body></html>